const raw = $input.first().json;
const body = raw.body || raw;
const args = body.args || {};

function normPhone(p) {
  const d = String(p || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.length === 10) return '91' + d;
  return d;
}

function shorten(t, limit = 120) {
  const s = String(t || '').replace(/\s+/g, ' ').trim();
  if (s.length <= limit) return s;
  return s.slice(0, limit - 1).trim() + '…';
}

function poorSummary(text) {
  const s = String(text || '').trim();
  if (!s || s.length > 420) return true;
  const low = s.toLowerCase();
  if (low.includes('caller said:') || low.includes('agent explained:')) return true;
  if ((low.match(/caller:/g) || []).length >= 2) return true;
  if (s.includes('|') && s.split('|').length >= 4) return true;
  if (s.startsWith('[') && low.includes('turns]')) return true;
  return false;
}

function composeSummary(topic, conversationFull, nextStep, outcome) {
  const lines = String(conversationFull || '')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
  const user = lines.filter((l) => l.startsWith('Caller:')).map((l) => l.slice(7).trim());
  const agent = lines.filter((l) => l.startsWith('Agent:')).map((l) => l.slice(6).trim());
  const mainAsk = shorten(user.find((u) => u.length > 4) || '', 100);
  const answer = shorten([...agent].reverse().find((a) => a.length > 20) || '', 130);
  const parts = [`Caller enquired about ${topic}.`];
  if (mainAsk) parts.push(`Key ask: ${mainAsk}.`);
  if (answer) parts.push(`Agent shared: ${answer}`);
  if (outcome) parts.push(`Call ended: ${outcome}.`);
  if (nextStep && nextStep !== 'None') parts.push(`Follow-up: ${nextStep}.`);
  return parts.join(' ').slice(0, 480);
}

const from = normPhone(body.from || args.caller_phone);
const callId = String(body.call_id || args.call_id || `CALL-${Date.now()}`);
let summary = String(args.summary || '').trim();
const topic = String(args.topic || args.caller_intent || 'General enquiry').trim();
let nextStep = String(args.next_step || '').trim();
const conversationFull = String(args.conversation_full || args.transcript || '').trim();
const durationSec = Number(args.duration_sec || 0);
const duration = args.duration || (durationSec ? `${durationSec} sec` : '');
const date = args.date || new Date().toISOString().slice(0, 10);
const timeIst = args.time_ist || args.time || '';
const business = body.business_name || 'ResilienceSoft';
const notify = normPhone(args.notify_whatsapp || body.notify_whatsapp || '');
const outcome = args.outcome || args.reason || 'Ended';
const turns =
  Number(args.transcript_turns || 0) ||
  (conversationFull ? conversationFull.split('\n').filter(Boolean).length : 0);

if (!nextStep) {
  if (args.appointment_booked === 'yes') nextStep = 'Appointment booked';
  else if (args.lead_captured === 'yes') nextStep = 'Lead — call back';
  else if (args.follow_up === 'callback') nextStep = 'Callback needed';
  else if (args.follow_up === 'team_notified') nextStep = 'Team notified';
  else nextStep = 'None';
}

if (poorSummary(summary)) {
  summary = composeSummary(topic, conversationFull, nextStep, outcome);
}
if (!summary) {
  summary = composeSummary(topic, conversationFull, nextStep, outcome);
}

const waText = [
  `📞 *${business} — Call*`,
  `${date}${timeIst ? ' · ' + timeIst : ''} · ${duration}`,
  `Caller: ${from || 'unknown'}`,
  `Topic: ${topic}`,
  `Next: ${nextStep}`,
  '',
  summary,
].join('\n').trim();

const waBody = notify
  ? {
      messageObject: {
        messaging_product: 'whatsapp',
        to: notify,
        type: 'text',
        text: { body: waText },
      },
      enableLog: true,
    }
  : null;

return [
  {
    json: {
      call_id: callId,
      date,
      time: timeIst,
      caller: from,
      duration,
      topic,
      summary,
      next_step: nextStep,
      turns,
      transcript: conversationFull,
      notify_whatsapp: notify,
      waBody,
      hasWhatsApp: !!waBody,
    },
  },
];

const raw = $input.first().json;
const body = raw.body || raw;
const action = body.action || 'unknown';
const args = body.args || {};
const callId = body.call_id || `CALL-${Date.now()}`;
const from = String(body.from || '').replace(/\D/g, '');
const now = new Date();
const date = now.toISOString().slice(0, 10);
const timeIst = now.toLocaleTimeString('en-IN', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: true,
  timeZone: 'Asia/Kolkata',
});

function detailsFor(actionName) {
  const bits = [];
  if (args.name) bits.push(`Name: ${args.name}`);
  if (args.phone) bits.push(`Phone: ${args.phone}`);
  if (args.service) bits.push(`Service: ${args.service}`);
  if (args.date) bits.push(`Date: ${args.date}`);
  if (args.time) bits.push(`Time: ${args.time}`);
  if (args.interest) bits.push(`Interest: ${args.interest}`);
  if (args.notes) bits.push(`Notes: ${args.notes}`);
  if (args.message) bits.push(String(args.message));
  if (actionName === 'lookup_knowledge' && args.query) bits.push(`Query: ${args.query}`);
  return bits.join(' · ').slice(0, 500) || '—';
}

let response;
let sheetRow = null;

switch (action) {
  case 'lookup_knowledge': {
    const q = String(args.query || '').trim();
    response = {
      status: 'ok',
      action,
      query: q,
      results: '',
      message:
        'No n8n knowledge index configured. Voice-agent should answer using local business_knowledge.md search.',
    };
    break;
  }
  case 'book_appointment': {
    response = {
      status: 'confirmed',
      action,
      message: `Appointment noted${args.date ? ' for ' + args.date : ''}${args.time ? ' at ' + args.time : ''}.`.trim(),
    };
    sheetRow = {
      call_id: callId,
      date,
      time: timeIst,
      caller: from,
      action: 'book_appointment',
      details: detailsFor('book_appointment'),
      status: 'confirmed',
    };
    break;
  }
  case 'create_lead': {
    response = {
      status: 'lead_created',
      action,
      message: 'Lead captured. The team will follow up shortly.',
    };
    sheetRow = {
      call_id: callId,
      date,
      time: timeIst,
      caller: from,
      action: 'create_lead',
      details: detailsFor('create_lead'),
      status: 'lead_created',
    };
    break;
  }
  case 'send_notification': {
    response = {
      status: 'notified',
      action,
      message: 'Your message has been passed to the team.',
    };
    sheetRow = {
      call_id: callId,
      date,
      time: timeIst,
      caller: from,
      action: 'send_notification',
      details: detailsFor('send_notification'),
      status: 'notified',
    };
    break;
  }
  default: {
    response = { status: 'ok', action, message: `Action '${action}' received.` };
  }
}

return [{ json: { ...response, sheetRow } }];

const h = $('Handle Action').first().json;
const { sheetRow, ...response } = h;
return [{ json: response }];

// Only 8 fields — prevents Google Sheets from creating extra columns
const b = $('Build Call Log').first().json;
return [
  {
    json: {
      call_id: b.call_id,
      date: b.date,
      time: b.time,
      caller: b.caller,
      duration: b.duration,
      topic: b.topic,
      summary: b.summary,
      next_step: b.next_step,
    },
  },
];
